// ponytail: svgPathToGraphics reads SVG path M/C/L/Z commands, sampling cubic beziers
// via 8-point linear segments (Phaser Graphics lacks bezierCurveTo).
// viewBox = {vw, vh} from the SVG. Scale & center at (cx, cy).
function sampleCubic(
  p0x: number, p0y: number,
  c1x: number, c1y: number,
  c2x: number, c2y: number,
  p1x: number, p1y: number,
  t: number,
): [number, number] {
  const u = 1 - t
  const u3 = u * u * u
  const t3 = t * t * t
  const u2t = 3 * u * u * t
  const ut2 = 3 * u * t * t
  return [
    u3 * p0x + u2t * c1x + ut2 * c2x + t3 * p1x,
    u3 * p0y + u2t * c1y + ut2 * c2y + t3 * p1y,
  ]
}

function svgPathToGraphics(
  g: Phaser.GameObjects.Graphics,
  path: string,
  vw: number, vh: number,
  cx: number, cy: number,
  iconSize: number,
  fill: number,
  stroke: number,
  strokeAlpha: number = 0.4,
  lineW: number = 1.5,
): void {
  const sc = iconSize / Math.max(vw, vh)
  const ox = cx - vw / 2 * sc
  const oy = cy - vh / 2 * sc
  function sx(x: number) { return ox + x * sc }
  function sy(y: number) { return oy + y * sc }

  const segs = path.split(/(?=M)/).filter(s => s.trim())
  g.fillStyle(fill, 1)
  for (const seg of segs) {
    const cmds = seg.match(/[MCZL][\d\s.,\-e]*/g) || []
    let prevX = 0, prevY = 0
    g.beginPath()
    for (const raw of cmds) {
      const cmd = raw[0]
      const nums = raw.slice(1).trim().split(/[\s,]+/).filter(s => s).map(Number)
      if (cmd === 'M' && nums.length >= 2) {
        prevX = sx(nums[0]); prevY = sy(nums[1])
        g.moveTo(prevX, prevY)
        // implicit subsequent pairs are lineTos
        for (let i = 2; i + 1 < nums.length; i += 2) {
          prevX = sx(nums[i]); prevY = sy(nums[i + 1])
          g.lineTo(prevX, prevY)
        }
      } else if (cmd === 'C' && nums.length >= 6) {
        for (let i = 0; i + 5 < nums.length; i += 6) {
          const c1x = sx(nums[i]), c1y = sy(nums[i + 1])
          const c2x = sx(nums[i + 2]), c2y = sy(nums[i + 3])
          const ex = sx(nums[i + 4]), ey = sy(nums[i + 5])
          for (let j = 1; j <= 8; j++) {
            const t = j / 8
            const [px, py] = sampleCubic(prevX, prevY, c1x, c1y, c2x, c2y, ex, ey, t)
            g.lineTo(px, py)
          }
          prevX = ex; prevY = ey
        }
      } else if (cmd === 'L' && nums.length >= 2) {
        for (let i = 0; i + 1 < nums.length; i += 2) {
          prevX = sx(nums[i]); prevY = sy(nums[i + 1])
          g.lineTo(prevX, prevY)
        }
      } else if (cmd === 'Z') {
        g.closePath()
      }
    }
    // SVG paths implicitly close subpaths without Z — flush fill/stroke per subpath
    g.closePath()
    g.fillPath()
    g.lineStyle(lineW, stroke, strokeAlpha)
    g.strokePath()
  }
}

